(function(){let e=globalThis;e.onmessage=async({data:t})=>{try{if(typeof OffscreenCanvas>`u`)throw Error(`OffscreenCanvas unavailable`);let n=new OffscreenCanvas(t.width,t.height),r=n.getContext(`2d`);if(!r)throw Error(`thumbnail canvas unavailable`);r.drawImage(t.bitmap,0,0,t.width,t.height),t.bitmap.close();let i=await n.convertToBlob({type:`image/jpeg`,quality:.65});e.postMessage({id:t.id,blob:i})}catch(n){try{t.bitmap.close()}catch{}e.postMessage({id:t.id,error:n instanceof Error?n.message:`thumbnail encode failed`})}}})();